function solve(s) {
  const fact = (n) => (n <= 1 ? 1 : n * fact(n - 1));
  const counts = {};
  for (const c of s) counts[c] = (counts[c] || 0) + 1;
  let result = fact(s.length);
  for (const c of Object.values(counts)) result /= fact(c);
  return result;
}

